**What this code covers**

- Evaluates a math expression.
- Gets current weather for a city.
- Searches the web for information.
- Converts between units.
- No other dependencies needed!
- STEP 1: Write normal Python functions
- Replace with real API (SerpAPI, Tavily, etc.)
- STEP 2: Map function names → actual functions

**Defines:** `calculator()`, `weather_tool()`, `web_search()`, `unit_converter()`, `summarizer()`

```python name=tools.py
# pip install openai
# No other dependencies needed!

import math
import json

# ─────────────────────────────────────────────
# STEP 1: Write normal Python functions
# ─────────────────────────────────────────────

def calculator(expression: str) -> str:
    """Evaluates a math expression."""
    try:
        allowed = {"__builtins__": {}, "math": math}
        result = eval(expression, allowed)
        return f"Result: {result}"
    except Exception as e:
        return f"Error evaluating expression: {e}"

def weather_tool(city: str) -> str:
    """Gets current weather for a city."""
    data = {
        "london":   "15°C, cloudy",
        "new york": "22°C, sunny",
        "tokyo":    "28°C, humid",
        "paris":    "18°C, windy",
    }
    return data.get(city.lower(), f"{city}: 20°C, partly cloudy")

def web_search(query: str) -> str:
    """Searches the web for information."""
    # Replace with real API (SerpAPI, Tavily, etc.)
    return f"Search results for '{query}': Found relevant articles about {query}."

def unit_converter(value: float, from_unit: str, to_unit: str) -> str:
    """Converts between units."""
    table = {
        ("km",        "miles"):      lambda x: x * 0.621371,
        ("miles",     "km"):         lambda x: x * 1.60934,
        ("celsius",   "fahrenheit"): lambda x: x * 9/5 + 32,
        ("fahrenheit","celsius"):    lambda x: (x - 32) * 5/9,
        ("kg",        "lbs"):        lambda x: x * 2.20462,
        ("lbs",       "kg"):         lambda x: x * 0.453592,
    }
    key = (from_unit.lower(), to_unit.lower())
    if key in table:
        result = table[key](value)
        return f"{value} {from_unit} = {result:.4f} {to_unit}"
    return f"Sorry, conversion from {from_unit} to {to_unit} is not supported."

def summarizer(text: str) -> str:
    """Summarizes long text into key points."""
    words = text.split()
    if len(words) > 20:
        return f"Summary: {' '.join(words[:15])}... [{len(words)} total words condensed]"
    return f"Summary: {text}"

# ─────────────────────────────────────────────
# STEP 2: Map function names → actual functions
# This is how we call them when OpenAI says so
# ─────────────────────────────────────────────

FUNCTIONS_MAP = {
    "calculator":     calculator,
    "weather_tool":   weather_tool,
    "web_search":     web_search,
    "unit_converter": unit_converter,
    "summarizer":     summarizer,
}

# ─────────────────────────────────────────────
# STEP 3: Describe tools in OpenAI's JSON format
# OpenAI reads THIS to decide which tool to call
# ─────────────────────────────────────────────

TOOLS_SCHEMA = [
    {
        "type": "function",
        "function": {
            "name": "calculator",
            "description": (
                "Evaluates a math expression. "
                "Use ONLY for complex arithmetic. "
                "Do NOT use for simple math like 2+2."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "expression": {
                        "type": "string",
                        "description": "Math expression to evaluate, e.g. '25 * 48' or 'math.sqrt(144)'"
                    }
                },
                "required": ["expression"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "weather_tool",
            "description": (
                "Gets real-time weather for a city. "
                "Use ONLY when user asks about weather."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "city": {
                        "type": "string",
                        "description": "The city name, e.g. 'London' or 'Tokyo'"
                    }
                },
                "required": ["city"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "web_search",
            "description": (
                "Searches the internet for current facts or recent events. "
                "Use ONLY for things you don't know or real-time info."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "query": {
                        "type": "string",
                        "description": "Search query string"
                    }
                },
                "required": ["query"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "unit_converter",
            "description": (
                "Converts between units like km/miles, celsius/fahrenheit, kg/lbs. "
                "Use ONLY when user explicitly asks to convert units."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "value":     {"type": "number", "description": "Numeric value to convert"},
                    "from_unit": {"type": "string", "description": "Source unit, e.g. 'km', 'celsius'"},
                    "to_unit":   {"type": "string", "description": "Target unit, e.g. 'miles', 'fahrenheit'"}
                },
                "required": ["value", "from_unit", "to_unit"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "summarizer",
            "description": (
                "Summarizes a long block of text. "
                "Use ONLY when user explicitly asks for a summary."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "text": {
                        "type": "string",
                        "description": "The text to summarize"
                    }
                },
                "required": ["text"]
            }
        }
    },
]
